mapper.sql:
r.merchant_id = #{ownerMemberId}
and (
  exists (
    select 1 from merchant_aftercare_response scoped
    where scoped.refund_application_id = r.id and scoped.merchant_id = #{merchantId}
  )
  or (
    not exists (
      select 1 from merchant_aftercare_response bound
      where bound.refund_application_id = r.id
    )
    and not exists (
      select 1 from mms_merchant sibling
      where sibling.member_id = #{ownerMemberId} and sibling.id <> #{merchantId}
        and sibling.status = 1 and sibling.account_status = 1 and sibling.del_flag = 0
    )
  )
)

left join (
    select merchant_id, refund_application_id, max(id) as latest_opinion_id
    from merchant_aftercare_response
    where merchant_id = #{merchantId}
      and decision in ('AGREE', 'REJECT')
    group by merchant_id, refund_application_id
) latest on latest.refund_application_id = r.id
left join merchant_aftercare_response opinion on opinion.id = latest.latest_opinion_id
  and opinion.merchant_id = #{merchantId}

mapper.select:
select id, refund_application_id, merchant_id, merchant_owner_member_id, actor_member_id,
       actor_role_code, decision, content, evidence_url, request_id, create_time
from merchant_aftercare_response
where merchant_id = #{merchantId}
  and refund_application_id = #{refundId}
order by id asc

select count(1)
from merchant_aftercare_response
where evidence_url = #{evidenceKey}
  and refund_application_id <> #{refundId}
